// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { ArrayLike } from '@stdlib/types/array';

/**
* If provided a value, the accumulator function returns an updated moving arithmetic mean and unbiased sample variance. If not provided a value, the accumulator function returns the current moving arithmetic mean and unbiased sample variance.
*
* ## Notes
*
* -   If provided `NaN`, the value is **ignored** and the accumulator state is **not updated**.
*
* @param x - input value
*
* @returns output array or null
*/
type accumulator = ( x?: number ) => ArrayLike<number> | null;

/**
* Returns an accumulator function which incrementally computes a moving arithmetic mean and unbiased sample variance while **skipping NaN values**.
*
* ## Notes
*
* -   The `window` parameter defines the number of most-recent **valid (non-NaN)** values used to compute the moving statistics.
* -   Until at least one valid value has been provided, the accumulator returns `null`.
* -   If only one valid value has been observed, the sample variance is `0.0`.
*
* @param out - output array
* @param window - window size
* @throws window size must be a positive integer
* @returns accumulator function
*
*/
declare function incrnanmmeanvar( out: ArrayLike<number>, window: number ): accumulator;

/**
* Returns an accumulator function which incrementally computes a moving arithmetic mean and unbiased sample variance while **skipping NaN values**.
*
* ## Notes
*
* -   The `window` parameter defines the number of most-recent **valid (non-NaN)** values used to compute the moving statistics.
* -   Until at least one valid value has been provided, the accumulator returns `null`.
* -   If only one valid value has been observed, the sample variance is `0.0`.
*
* @param window - window size
* @throws window size must be a positive integer
* @returns accumulator function
*
* @example
* var incrnanmmeanvar = require( '@stdlib/stats/incr/nanmmeanvar' );
*
* var accumulator = incrnanmmeanvar( 3 );
*
* var v = accumulator();
* // returns null
*
* v = accumulator( 2.0 );
* // returns [ 2, 0 ]
*
* v = accumulator( NaN );
* // returns [ 2, 0 ]
*
* v = accumulator( 4.0 );
* // returns [ 3, 2 ]
*
* v = accumulator( 6.0 );
* // returns [ 4, 4 ]
*
* v = accumulator( NaN );
* // returns [ 4, 4 ]
*
* v = accumulator( 8.0 );
* // Window is [4,6,8]
* // mean = 6, variance = ((4-6)^2+(6-6)^2+(8-6)^2) / 2 = 4
* // returns [ 6, 4 ]
*
* v = accumulator();
* // returns [ 6, 4 ]
*/
declare function incrnanmmeanvar( window: number ): accumulator;


// EXPORTS //

export = incrnanmmeanvar;
